    // We'll check if name contains "launcher".
    if (!name.contains("launcher")) {
        return;
    }

    FolderConfiguration config = context.getFolderConfiguration();
    if (config == null || config.getDensityQualifier() == null) {
        return;
    }
    Density density = config.getDensityQualifier().getValue();
    if (density == null || density == Density.NODPI || density == Density.ANYDPI) {
        return;
    }

    int expectedSize = Math.round(48 * density.getDpiValue() / 160f);
